let mode = flow.get("sim_mode") || "normal";
let currentDist = flow.get("current_dist") || 175.0;
// Bomba ativa: alivia +2.5cm por ciclo no nivel da agua
let pumpActive = flow.get("pump_active") || false;
let pumpRelief = pumpActive ? 2.5 : 0;
if (mode === "critical") {
    currentDist = Math.max(15.0, currentDist - 4.0 + (Math.random() * 2 - 1) + pumpRelief);
} else {
    currentDist = Math.min(180.0, currentDist + 5.0 + (Math.random() * 2 - 1) + pumpRelief);
}
flow.set("current_dist", currentDist);
msg.payload = { sensor_id: "bueiro_01", distancia_cm: parseFloat(currentDist.toFixed(1)), timestamp: Date.now() };
return msg;

flow.set("sim_mode", "normal");
flow.set("current_dist", 175.0);
msg.payload = { sensor_id: "bueiro_01", distancia_cm: 175.0, timestamp: Date.now() };
return msg;

flow.set("sim_mode", "critical");
flow.set("current_dist", 24.0);
msg.payload = { sensor_id: "bueiro_01", distancia_cm: 24.0, timestamp: Date.now() };
return msg;

let current = flow.get("pump_manual") || false;
let next = !current;
flow.set("pump_manual", next);
let d = flow.get("current_dist") || 175.0;
let lv = 200.0 - d;
msg.payload = {
    sensor_id: "bueiro_01",
    distancia_cm: d,
    nivel_agua_cm: parseFloat(lv.toFixed(1)),
    nivel_agua_pct: parseFloat(((lv / 200.0) * 100).toFixed(1)),
    status: "MANUAL"
};
msg.manual_override = next;
return msg;

const data = msg.payload;
const sensorDepth = 200.0;
const dist = typeof data.distancia_cm === "number" ? data.distancia_cm : 200;
let waterLevelCm = sensorDepth - dist;
if (waterLevelCm < 0) waterLevelCm = 0;
if (waterLevelCm > sensorDepth) waterLevelCm = sensorDepth;
let waterLevelPct = parseFloat(((waterLevelCm / sensorDepth) * 100).toFixed(1));
let status = "NORMAL";
if (waterLevelPct >= 80) status = "CRITICO (TRANSBORDAMENTO)";
else if (waterLevelPct >= 50) status = "ATENCAO (ELEVADO)";
else status = "NORMAL (SEGURO)";
msg.payload = {
    sensor_id: data.sensor_id || "bueiro_01",
    distancia_cm: dist,
    nivel_agua_cm: parseFloat(waterLevelCm.toFixed(1)),
    nivel_agua_pct: waterLevelPct,
    status: status
};
return [
    { payload: waterLevelPct },
    { payload: waterLevelPct, topic: "Bueiro 01 (%)" },
    { payload: status + " [" + waterLevelPct + "% - " + waterLevelCm.toFixed(1) + " cm]" },
    { payload: msg.payload }
];

// =====================================================
// FUNCAO 1: Predicao Hidrologica de ETA (Nova)
// Calcula o tempo estimado ate a calha atingir cota
// maxima, com base na taxa de subida atual (cm/min).
// =====================================================
const data = msg.payload;
const SENSOR_DEPTH_CM = 200.0;
const CRITICAL_PCT = 80.0;
let levelCm = (typeof data.nivel_agua_cm === "number") ? data.nivel_agua_cm : 0;
let levelPct = (typeof data.nivel_agua_pct === "number") ? data.nivel_agua_pct : 0;
let prev = flow.get("eta_prev_reading") || null;
let now = Date.now();
let etaText = "Calha estavel — sem elevacao detectada";
if (prev !== null) {
    let dtMin = (now - prev.time) / 60000.0;
    if (dtMin > 0.01) {
        let rate = (levelCm - prev.level) / dtMin;
        if (rate > 0.3) {
            let remaining = SENSOR_DEPTH_CM - levelCm;
            let etaMin = parseFloat((remaining / rate).toFixed(1));
            if (levelPct >= CRITICAL_PCT) {
                etaText = "TRANSBORDANDO AGORA — Protocolo de emergencia ativo!";
            } else if (etaMin <= 5) {
                etaText = "TRANSBORDO IMINENTE em ~" + etaMin + " min (+" + rate.toFixed(1) + " cm/min)";
            } else if (etaMin <= 15) {
                etaText = "Elevacao rapida — transbordo em ~" + etaMin + " min (+" + rate.toFixed(1) + " cm/min)";
            } else {
                etaText = "Subindo — transbordo em ~" + etaMin + " min (+" + rate.toFixed(1) + " cm/min)";
            }
        } else if (rate < -0.3) {
            etaText = "Nivel em queda — escoamento ativo (" + Math.abs(rate).toFixed(1) + " cm/min)";
        }
    }
}
flow.set("eta_prev_reading", { level: levelCm, time: now });
msg.payload = etaText;
return msg;

// =====================================================
// FUNCAO 2: Atuador Edge — Bomba de Alivio (Nova)
// Aciona bomba automaticamente (nivel >= 80%) ou por
// comando manual. Registra log circular de ativacoes.
// =====================================================
const data = msg.payload;
let levelPct = (typeof data.nivel_agua_pct === "number") ? data.nivel_agua_pct : 0;
let manualOverride = (msg.manual_override !== undefined)
    ? msg.manual_override
    : (flow.get("pump_manual") || false);
if (msg.manual_override !== undefined) {
    flow.set("pump_manual", manualOverride);
}
let autoPump = levelPct >= 80;
let pumpActive = manualOverride || autoPump;
let wasActive = flow.get("pump_active") || false;
flow.set("pump_active", pumpActive);
if (pumpActive && !wasActive) {
    let reason = autoPump ? "Automatico (nivel >= 80%)" : "Comando manual do operador";
    let log = flow.get("pump_log") || [];
    log.unshift({ time: new Date().toLocaleTimeString("pt-BR"), reason: reason, level: levelPct });
    if (log.length > 10) log.pop();
    flow.set("pump_log", log);
    node.warn("[BOMBA] Acionada — " + reason + " | Nivel: " + levelPct + "%");
} else if (!pumpActive && wasActive) {
    node.warn("[BOMBA] Desligada | Nivel: " + levelPct + "%");
}
let statusText;
if (pumpActive) {
    let mode = (manualOverride && !autoPump) ? "Manual (150 L/s)" : "Auto-Contingencia Edge (120 L/s)";
    statusText = "ATIVA — " + mode + " | Nivel: " + levelPct + "%";
} else {
    statusText = "Standby — Bomba desligada";
}
msg.payload = statusText;
msg.pumpActive = pumpActive;
return msg;
